#!/usr/bin/env python3
"""Build the interbot/iPhone investigation index and explanatory page."""
from pathlib import Path
import json,html,re,hashlib,importlib.util
ROOT=Path(__file__).resolve().parents[1]
REPORTS=[('interbot-client-paths','Les conversations entre bots'),('interbot-mobile-protocol','Les paquets et l’iPhone'),('server-context-residual','Contexte et mémoire'),('server-orchestration-residual','Réveil, skills et frontières serveur')]
def esc(v):return html.escape(str(v),quote=True)
def main():
 rows=[]
 for name,label in REPORTS:
  path=ROOT/'evidence'/(name+'.json');v=json.loads(path.read_text())
  rows.append({'id':name,'label':label,'report':v['report'],'ledger':str(path.relative_to(ROOT)),'ledger_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'findings':len(v['findings']),'anchors':len(v['anchors'])})
 agg={'schema':1,'target':'Grok Bot macOS 0.70.2 saved artifact','phone_selected_by_user':'iPhone','authenticated_runtime_verified':False,'native_ios_artifact_available':False,'rust_changes_performed':False,'reports':rows,
  'counts':{'reports':4,'findings':sum(r['findings'] for r in rows),'anchors':sum(r['anchors'] for r in rows),'javascript_search_files':600},
  'coverage':[
   {'question':'Messages directs et réponses entre bots','status':'partially_answered','missing':'Initiateur/service distant, ACL, ordre et déduplication réelle.'},
   {'question':'Tours de groupe et sous-agents','status':'partially_answered','missing':'Ordonnanceur et contexte délégué effectif; ces mécanismes restent distincts.'},
   {'question':'Contexte texte et compaction','status':'partially_answered','missing':'Constructeur de prompt et consommateur des bornes de résumé dans le moteur.'},
   {'question':'Mémoire durable et oubli','status':'partially_answered','missing':'Correction, suppression et injection; partage client mieux retracé.'},
   {'question':'Démonstration vers skill','status':'unresolved','missing':'Capture mobile/cloud, job d’extraction, recording→skill et validation.'},
   {'question':'Budgets et fin métier','status':'unresolved','missing':'Compteurs/politique effectifs et prédicat terminal du moteur.'},
   {'question':'Connexion iPhone↔Mac','status':'partially_answered','missing':'App native iOS, auth native, inscription APNs et transport de fond.'}],
  'contracts':'evidence/interbot-message-contracts.json','searches':'evidence/interbot-mobile-search.json','rea_trace':'evidence/interbot-rea-trace.json'}
 (ROOT/'evidence/communications-investigation.json').write_text(json.dumps(agg,ensure_ascii=False,indent=2)+'\n')
 n=agg['counts'];parts=['# Comment les bots se parlent et comment l’iPhone rejoint le Mac',
  f"Cette passe conserve {n['findings']} constats dans quatre rapports et {n['anchors']} extraits hashés. Les messages interbot, leur présentation et les contrats de tours de groupe sont mieux établis. Le volet iPhone retrace les interfaces communes et les consommateurs Mac; il ne contient pas le binaire natif iOS ni les services privés.",
  '## Entre deux bots',
  'Le protocole prévoit du texte avec expéditeur, destinataire, messageId, date et replyToId éventuel. Le retour immédiat renseigne la livraison; le destinataire peut répondre par un autre message lié au premier. Dans le client, fromAgent/toAgent servent à regrouper les échanges et reconstruire une conversation avec le pair. Les cartes envoyées/reçues ont des consommateurs actifs.',
  'Un @bot dans le composeur devient une mention structurée dans richText et un @nom dans le texte. Ce chemin ne déclenche pas lui-même un appel direct SendGrokBotAgentMessage. Le serveur interprète la demande et les mentions; son choix de destinataire n’est pas récupéré.',
  'Les groupes possèdent un autre protocole : un membre reçoit un tour, une liste de pairs et de nouveaux messages, une deadline et un nonce. Le retour peut publier, passer, expirer ou échouer. Une délégation à un sous-agent possède encore d’autres contrats. La présence de ces trois circuits n’établit pas un unique moteur commun.',
  'Détails : [consommateurs et conversations](interbot-client-paths.md), [enveloppes et tours](interbot-mobile-protocol.md). Les [paquets illustratifs](../evidence/interbot-message-contracts.json) sont inventés à partir des champs récupérés; aucune capture réelle n’est revendiquée.',
  '## Entre ton iPhone et ton Mac',
  'Le Mac lit une liste d’appareils du compte qui reconnaît ios, avec identité et état connecté. Les messages transportent bot, session et identité de message; les contrats distinguent desktop/mobile et plusieurs origines mobiles. Le Mac reçoit ensuite des lignes et états depuis un flux serveur authentifié, avec curseur et génération pour reprendre après déconnexion.',
  'Cela soutient une architecture de continuité par les services du compte. Une connexion directe iPhone↔Mac n’est pas établie dans les chemins inspectés. Le code de login iOS, de synchronisation en arrière-plan et d’inscription push n’est pas livré dans cet artefact Mac. Les hits Bluetooth concernent des routes audio, et pairing vise principalement 1Password.',
  'La carte mobile de permission sur Mac affiche un état et une note pour l’autre appareil. Le Mac ne possède pas le bouton ni le handler d’autorisation iOS dans ce composant. Une demande d’outil sur le Mac passe par une autre route backend→machine ciblée→exécuteur local, avec ses permissions. Synchroniser le texte ne suffit pas à autoriser cet outil.',
  'Détails : [connexion iPhone↔Mac](interbot-mobile-protocol.md).',
  '## Ce que la recherche supplémentaire a trouvé',
  'Le partage de mémoire possède un consommateur lazy réel : sélection par factIds, lots de 100 et conservation locale des lots déjà réussis après un échec ultérieur. La préparation d’image envoie le brouillon et jusqu’à cinq textes humains filtrés; elle exclut les messages entre bots dans cette projection. Cela ne reconstitue pas le prompt texte général.',
  'Une carte de formulaire déjà réglée peut retenter la remise du réveil du bot via submitUserForm avec values vide. Le retour accepted ne prouve pas encore la reprise du moteur. L’import de fichiers texte produit et écrit de vraies skills; ce circuit est distinct de l’apprentissage d’une démonstration. Le repli maxRunning=32 reste une configuration sans consommateur Grok retrouvé.',
  'Détails : [contexte et mémoire](server-context-residual.md), [réveil et skills](server-orchestration-residual.md).',
  '## Les frontières encore ouvertes',
  '| Question | Statut | Preuve encore nécessaire |\n|---|---|---|\n'+'\n'.join(f"| {r['question']} | {r['status']} | {r['missing']} |" for r in agg['coverage']),
  'Ces frontières ne sont pas résolues par un nom de SDK ou une valeur de repli. Les corps du moteur box/Temporal et l’app iOS, ou des observations passives ciblées, sont nécessaires pour les trancher. La passe complète les preuves client et ne prétend pas avoir récupéré les serveurs.',
  '## Rapports et vérification',
  '| Rapport | Constats | Extraits | Ledger |\n|---|---:|---:|---|\n'+'\n'.join(f"| [{r['label']}](../{r['report']}) | {r['findings']} | {r['anchors']} | [JSON](../{r['ledger']}) |" for r in rows),
  'La [vue navigable](../.lavish/communications-grokbot.html) complète la [synthèse précédente des neuf sujets](goal-nine-topics.md). Le [vérificateur](../tools/verify-communications.py) contrôle les ledgers, le corpus des recherches, les extraits et les contrats projetés. Aucune implémentation Rust n’a été modifiée par cette enquête.']
 (ROOT/'reports/communications-investigation.md').write_text('\n\n'.join(parts)+'\n')
 spec=importlib.util.spec_from_file_location('detail',ROOT/'tools/build-investigation-detail.py');d=importlib.util.module_from_spec(spec);spec.loader.exec_module(d)
 css=re.search(r'<style>([\s\S]*?)</style>',(ROOT/'tools/investigation-detail-template.html').read_text()).group(1)
 extra='dl{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:8px 16px;font-size:13px}dt{font-weight:600;overflow-wrap:anywhere}dd{margin:0;overflow-wrap:anywhere}.packet{padding:20px;border:1px solid var(--line);border-radius:12px;background:var(--pane)}.selectors{display:flex;gap:8px;flex-wrap:wrap}.selectors button[aria-pressed=true]{background:var(--tint);border-color:var(--accent)}.packet .bubble{font-size:20px;margin:20px 0}h2{max-width:42ch}@media(max-width:640px){dl{grid-template-columns:minmax(0,1fr)}dd{padding-bottom:10px;border-bottom:1px solid var(--line)}}'
 details=[];sources=[]
 for r in rows:
  report=ROOT/r['report'];d.evidence_href(str(report),report);d.evidence_href(str(ROOT/r['ledger']),report)
  details.append(f"<details class='report' id='report-{r['id']}'><summary>{esc(r['label'])} · {r['findings']} constats · {r['anchors']} extraits</summary><div class='report-body'>{d.markdown(report)}</div></details>")
  sources.append(f"<li><a href='investigation-detail/{r['ledger']}'>{esc(r['label'])} — ledger</a></li>")
 for path in ['reports/communications-investigation.md','evidence/communications-investigation.json','evidence/interbot-message-contracts.json','evidence/interbot-mobile-search.json','evidence/interbot-rea-trace.json','tools/build-interbot-protocol.py','tools/index-interbot-mobile.py','tools/verify-communications.py']:
  assert (ROOT/path).is_file(),path
  d.evidence_href(str(ROOT/path),ROOT/'reports/communications-investigation.md')
  sources.append(f"<li><a href='investigation-detail/{path}'>{esc(path)}</a></li>")
 nav=''.join(f"<button role='tab' data-topic='{i}' id='tab-{i}' aria-controls='panel-{i}' aria-selected='{str(k==0).lower()}' tabindex='{0 if k==0 else -1}'>{t}</button>" for k,(i,t) in enumerate([('bots','Entre bots'),('rooms','En groupe'),('iphone','iPhone ↔ Mac'),('unknown','Encore inconnu')]))
 cases=json.loads((ROOT/'evidence/interbot-message-contracts.json').read_text())['examples']
 panels=f"""<section class='panel' id='panel-bots' role='tabpanel' aria-labelledby='tab-bots'><p class='eyebrow'>Messages directs</p><h2>Un bot adresse du texte à un autre bot, qui peut répondre.</h2><p>Le client relie expéditeur, destinataire et réponses. Le retour de livraison et la réponse du destinataire sont deux objets différents. Le service qui lance et traite cet échange reste distant.</p><article class='packet' id='message-example'><strong>Exemple inventé à partir du contrat</strong><div class='selectors'><button data-packet='direct' aria-pressed='true'>Demande</button><button data-packet='reply' aria-pressed='false'>Réponse</button><button data-packet='room' aria-pressed='false'>Tour de groupe</button></div><p class='bubble' id='packet-text'></p><dl id='packet-fields'></dl><p class='caption'>Projection pédagogique. Aucun message réel ni appel serveur n’a été exécuté.</p></article><div class='boundary'><article id='mentions'><h3>Une mention a son propre chemin</h3><p>@bot devient une mention structurée et du texte. Le serveur interprète ensuite la demande; le clic ne prouve pas un envoi interbot direct.</p></article><article id='history'><h3>Le contexte complet reste à établir</h3><p>L’enveloppe ne contient pas tout l’historique ni la mémoire. Les enrichissements ajoutés par le backend sont inconnus.</p></article></div></section>
 <section class='panel' id='panel-rooms' role='tabpanel' aria-labelledby='tab-rooms' hidden><p class='eyebrow'>Tours corrélés</p><h2>Le groupe demande un tour à un membre et attend son résultat.</h2><div class='cards'><article id='room-request'><span class='number'>1 · Demande</span><h3>Membre et contexte</h3><p>Identité du membre, pairs, nouveaux textes, nonce, deadline et références parent.</p></article><article id='room-result'><span class='number'>2 · Retour</span><h3>Publier ou passer</h3><p>SENT, PASS, SKIPPED, TIMEOUT, CANCELLED ou ERROR; textes et posts structurés.</p></article><article id='room-intake'><span class='number'>3 · Réception</span><h3>Résultat reconnu</h3><p>ACCEPTED, UNKNOWN_NONCE ou HOST_UNAVAILABLE. Acceptation du tour et réception du résultat sont distinctes.</p></article></div><p>Ces contrats sont livrés. L’ordonnanceur qui choisit le membre, évite les cycles et enrichit son prompt n’est pas récupéré. Les sous-agents constituent une autre famille.</p></section>
 <section class='panel' id='panel-iphone' role='tabpanel' aria-labelledby='tab-iphone' hidden><p class='eyebrow'>Ton téléphone : iPhone</p><h2>Les preuves Mac soutiennent une continuité par les services du compte.</h2><figure class='figure'><svg viewBox='0 0 900 290' role='img' aria-label='iPhone et Mac reliés aux services du compte, avec voie native iPhone encore inconnue'><defs><marker id='arr' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='6' markerHeight='6' orient='auto-start-reverse'><path d='M0 0L10 5L0 10z' fill='var(--accent)'/></marker></defs><g id='phone-node'><title>Le contrat reconnaît iOS; l’application native n’a pas été inspectée</title><rect class='unknown' x='10' y='32' width='230' height='85' rx='12'/><text x='125' y='68' text-anchor='middle' font-size='24'>iPhone</text><text x='125' y='95' text-anchor='middle' font-size='16'>Partie native inconnue</text></g><g id='server-node'><title>Compte, machines, agents et sessions sont exposés par le backend</title><rect class='remote' x='335' y='32' width='230' height='85' rx='12'/><text x='450' y='68' text-anchor='middle' font-size='24'>Services du compte</text><text x='450' y='95' text-anchor='middle' font-size='16'>Agents et sessions</text></g><g id='mac-node'><title>Le Mac lit le roster et le flux authentifié avec ses curseurs</title><rect class='node' x='660' y='32' width='230' height='85' rx='12'/><text x='775' y='68' text-anchor='middle' font-size='24'>Mac</text><text x='775' y='95' text-anchor='middle' font-size='16'>Projection locale</text></g><g id='phone-contract'><title>Chemin mobile suggéré par les contrats, transport natif non vérifié</title><path class='edge' d='M240 75H335' stroke-dasharray='5 5' marker-end='url(#arr)'/></g><g id='mac-stream'><title>Requêtes Mac et flux serveur observés statiquement</title><path class='edge' d='M565 75H660' marker-start='url(#arr)' marker-end='url(#arr)'/></g><g id='local-tool-node'><title>Les outils exécutés sur le Mac utilisent une route adressée et leurs permissions</title><rect class='node' x='660' y='195' width='230' height='75' rx='12'/><text x='775' y='228' text-anchor='middle' font-size='21'>Exécuteur du Mac</text><text x='775' y='251' text-anchor='middle' font-size='15'>Machine et permissions</text></g><g id='local-tool-edge'><title>Canal de demandes local distinct de la synchronisation du texte</title><path class='edge' d='M565 92H610V232H660' marker-end='url(#arr)'/></g><text x='14' y='177' font-size='17'>Trait plein : consommateur Mac retracé.</text><text x='14' y='205' font-size='17'>Pointillés : contrat mobile, corps iOS absent.</text></svg><figcaption class='caption'>Aucun appairage direct iPhone↔Mac n’est établi. Login iOS, APNs et synchronisation en arrière-plan restent à observer dans l’application mobile.</figcaption></figure><div class='boundary'><article id='sync'><h3>Retrouver les conversations</h3><p>Bot, session, identités de messages, générations et curseurs relient les lignes. Le Mac reprend depuis le serveur après une coupure.</p></article><article id='mobile-permission'><h3>Autoriser un outil mobile</h3><p>La carte Mac indique l’état et renvoie à l’autre appareil. Son composant ne peut pas accorder une permission OS iPhone.</p></article></div></section>
 <section class='panel' id='panel-unknown' role='tabpanel' aria-labelledby='tab-unknown' hidden><p class='eyebrow'>Frontières vérifiables</p><h2>Les nouveaux consommateurs ne livrent pas le moteur serveur.</h2><div class='table-wrap'><table><thead><tr><th>Question</th><th>Preuve encore nécessaire</th></tr></thead><tbody>{''.join('<tr id="gap-'+str(i)+'"><td>'+esc(r['question'])+'</td><td>'+esc(r['missing'])+'</td></tr>' for i,r in enumerate(agg['coverage']))}</tbody></table></div><p>La recherche a aussi trouvé le partage de mémoire en lots de 100, une réparation de réveil après formulaire et l’import texte vers skills. Aucun de ces chemins ne prouve le moteur de compaction ou l’apprentissage Teach→skill.</p></section>"""
 markup=f"""<!doctype html><html lang='fr' data-theme='light'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Grok Bot — bots, iPhone et Mac</title><style>{css}{extra}</style></head><body><main><header><span class='brand'>Grok Bot · communications</span><div class='head-actions'><span class='badge'>Artefact 0.70.2</span><button id='theme' aria-label='Passer au thème sombre'>Thème sombre</button></div></header><p class='eyebrow'>Enquête complémentaire</p><h1>Comment les bots et les appareils se retrouvent.</h1><p class='lead'>Messages adressés, conversations de groupe et continuité iPhone↔Mac. Les chemins retracés et leurs frontières sont visibles séparément.</p><div class='note'><strong>{n['findings']} constats · {n['anchors']} extraits · 600 scripts recherchés.</strong> Analyse statique du client Mac. Aucun compte ni téléphone n’a été utilisé.</div><nav class='tabs' role='tablist' aria-label='Volet de communication'>{nav}</nav>{panels}<section id='reports'><p class='eyebrow'>Rapports complets</p>{''.join(details)}</section><footer id='sources'><details><summary>Sources et preuves</summary><ul>{''.join(sources)}</ul></details><p><a href='investigation-detail/reports/communications-investigation.md'>Synthèse source</a> · <a href='goal-neuf-sujets.html'>Les neuf sujets précédents</a></p><p>Design repris des tokens CSS du client Grok Bot, puisque cette page explique le produit original : fonds neutres, accent bleu et typographie système.</p></footer></main><script>
 const cases={json.dumps(cases,ensure_ascii=False)};
 function packet(id){{const p=cases[id];document.getElementById('packet-text').textContent=p.text??p.newMessages[0].text;const dl=document.getElementById('packet-fields');dl.replaceChildren();for(const [key,val]of Object.entries(p)){{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key;dd.textContent=typeof val==='object'?JSON.stringify(val):String(val);dl.append(dt,dd)}}for(const b of document.querySelectorAll('[data-packet]'))b.setAttribute('aria-pressed',String(b.dataset.packet===id))}}
 for(const b of document.querySelectorAll('[data-packet]'))b.addEventListener('click',()=>packet(b.dataset.packet));packet('direct');
 const tabs=[...document.querySelectorAll('[data-topic]')];function selectTopic(id,focus=false){{for(const t of tabs){{const on=t.dataset.topic===id;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;document.getElementById('panel-'+t.dataset.topic).hidden=!on;if(on&&focus)t.focus()}}history.replaceState(null,'','#'+id)}}for(const t of tabs){{t.addEventListener('click',()=>selectTopic(t.dataset.topic));t.addEventListener('keydown',e=>{{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let i=tabs.indexOf(t);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTopic(tabs[i].dataset.topic,true)}})}}const initial=location.hash.slice(1);if(tabs.some(t=>t.dataset.topic===initial))selectTopic(initial);document.getElementById('theme').addEventListener('click',e=>{{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';e.currentTarget.textContent=dark?'Thème clair':'Thème sombre';e.currentTarget.setAttribute('aria-label',dark?'Passer au thème clair':'Passer au thème sombre')}});
 </script></body></html>"""
 (ROOT/'.lavish/communications-grokbot.html').write_text(markup)
 print(json.dumps(n))
if __name__=='__main__':main()
